// src/chain/tip_notifier.ts
class TipNotifier {
  generationCounter = 0;
  wakePromise;
  wakeResolve;
  constructor() {
    this.wakePromise = this.makeWakePromise();
  }
  get generation() {
    return this.generationCounter;
  }
  makeWakePromise() {
    return new Promise((resolve) => {
      this.wakeResolve = resolve;
    });
  }
  notify() {
    this.generationCounter += 1;
    const resolve = this.wakeResolve;
    this.wakePromise = this.makeWakePromise();
    resolve();
  }
  async wait(lastGeneration, timeoutMs) {
    if (this.generationCounter !== lastGeneration) {
      return true;
    }
    if (timeoutMs === null) {
      await this.wakePromise;
      return true;
    }
    let timer;
    const timeoutPromise = new Promise((resolve) => {
      timer = setTimeout(() => resolve(false), timeoutMs);
    });
    try {
      return await Promise.race([this.wakePromise.then(() => true), timeoutPromise]);
    } finally {
      if (timer !== undefined)
        clearTimeout(timer);
    }
  }
}

