  errVal = null;
  closed = false;
  constructor(bgDB, targetHeight, targetHash, getBlock, maxCacheBytes) {
    this.bgDB = bgDB;
    this.bgUTXO = new UTXOManager(bgDB, maxCacheBytes);
    this.targetHeight = targetHeight;
    this.targetHash = targetHash;
    this.getBlock = getBlock;
  }
