// src/p2p/banman.ts
var DEFAULT_BAN_TIME = 24 * 60 * 60;

class BanManager {
  banned;
  datadir;
  isDirty;
  constructor(datadir) {
    this.datadir = datadir;
    this.banned = new Map;
    this.isDirty = false;
  }
  async load() {
    const path2 = `${this.datadir}/banlist.json`;
    try {
      const file = Bun.file(path2);
      if (await file.exists()) {
        const content = await file.text();
        const data = JSON.parse(content);
        if (data.version !== 1) {
          console.log(`Unknown banlist version: ${data.version}, recreating`);
          this.banned = new Map;
          return;
        }
        const now = Math.floor(Date.now() / 1000);
        for (const entry of data.bans) {
          if (now < entry.banUntil) {
            this.banned.set(entry.address, entry);
          }
        }
        console.log(`Loaded ${this.banned.size} banned addresses`);
      }
    } catch (error) {
      console.log("No banlist found or error loading, starting fresh");
      this.banned = new Map;
    }
  }
  async save() {
    if (!this.isDirty) {
      return;
    }
    const path2 = `${this.datadir}/banlist.json`;
    const data = {
      version: 1,
      bans: Array.from(this.banned.values())
    };
    try {
      await Bun.write(path2, JSON.stringify(data, null, 2));
      this.isDirty = false;
    } catch (error) {
      console.error("Failed to save banlist:", error);
    }
  }
  isBanned(address) {
    const entry = this.banned.get(address);
    if (!entry) {
      return false;
    }
    const now = Math.floor(Date.now() / 1000);
    if (now >= entry.banUntil) {
      this.banned.delete(address);
      this.isDirty = true;
      return false;
    }
    return true;
  }
  ban(address, banTime = DEFAULT_BAN_TIME, reason = "", absolute = false) {
    const now = Math.floor(Date.now() / 1000);
    const banUntil = absolute ? banTime : now + banTime;
    const entry = {
      address,
      banCreated: now,
      banUntil,
      reason
    };
    const existing = this.banned.get(address);
    if (existing && existing.banUntil >= banUntil) {
      return;
    }
    this.banned.set(address, entry);
    this.isDirty = true;
    this.save().catch((err) => console.error("Failed to save banlist:", err));
  }
  unban(address) {
    if (!this.banned.has(address)) {
      return false;
    }
    this.banned.delete(address);
    this.isDirty = true;
    this.save().catch((err) => console.error("Failed to save banlist:", err));
    return true;
  }
  clearBanned() {
    this.banned.clear();
    this.isDirty = true;
    this.save().catch((err) => console.error("Failed to save banlist:", err));
  }
  getBanned() {
    const now = Math.floor(Date.now() / 1000);
    const result = [];
    for (const [address, entry] of this.banned) {
      if (now < entry.banUntil) {
        result.push(entry);
      } else {
        this.banned.delete(address);
        this.isDirty = true;
      }
    }
    return result;
  }
  sweepBanned() {
    const now = Math.floor(Date.now() / 1000);
    let removed = 0;
    for (const [address, entry] of this.banned) {
      if (now >= entry.banUntil) {
        this.banned.delete(address);
        removed++;
      }
    }
    if (removed > 0) {
      this.isDirty = true;
      console.log(`Removed ${removed} expired bans`);
    }
  }
}

