function classifyCallbackError(err) {
  if (err === null || err === undefined)
    return "unknown";
  const raw = err instanceof Error ? err.message : String(err);
  if (raw.length === 0)
    return "unknown";
  const s = raw.toLowerCase();
  const consensusPatterns = [
    "tapscript execution failed",
    "tapscript",
    "script number too long",
    "script_size",
    "max_ops",
    "invalid signature",
    "script verification failed",
    "p2wpkh script verification failed",
    "p2wsh script verification failed",
    "taproot key-path signature verification failed",
    "taproot verify returned false",
    "parallel signature verification failed",
    "merkle root mismatch",
    "witness commitment mismatch",
    "duplicate input",
    "coinbase scriptsig",
    "exceeds max_money",
    "negative value",
    "transaction has no inputs",
    "transaction has no outputs",
    "missing utxo",
    "bip34 requires height",
    "bad-txns",
    "bad-blk",
    "non-final",
    "bad sigops",
    "sigops cost",
    "coinbase value",
    "immature coinbase",
    "sequence locks not satisfied",
    "does not match expected header"
  ];
  for (const pat of consensusPatterns) {
    if (s.includes(pat))
      return "consensus";
  }
  const chainstatePatterns = [
    "block_in_storage=no",
    "header_in_mem=true",
    "undo data missing",
    "missing undo",
    "failed to find block in chainstate",
    "chain_tip pointing at",
    "block body is missing",
    "lost in hard crash",
    "level_database_not_open",
    "leveldb: not found"
  ];
  for (const pat of chainstatePatterns) {
    if (s.includes(pat))
      return "chainstate";
  }
  return "unknown";
}
function bip22FromConnectError(err) {
  const s = err.toLowerCase();
  if (s.includes("non-final") || s.includes("nonfinal") || s.includes("bad-txns-nonfinal") || s.includes("sequence locks not satisfied") || s.includes("sequence lock"))
    return "bad-txns-nonfinal";
  if (s.includes("missing") && s.includes("utxo"))
    return "bad-txns-inputs-missingorspent";
  if (s.includes("missing utxo") || s.includes("inputs-missingorspent"))
    return "bad-txns-inputs-missingorspent";
  if (s.includes("coinbase") && s.includes("immature"))
    return "bad-txns-premature-spend-of-coinbase";
  if (s.includes("bad-txns-in-belowout") || s.includes("outputs exceed inputs"))
    return "bad-txns-in-belowout";
  if (s.includes("bad-cb-amount") || (s.includes("coinbase value") || s.includes("coinbase output")) && s.includes("exceeds") || s.includes("coinbase") && s.includes("pays too much"))
    return "bad-cb-amount";
  if (s.includes("accumulated-fee-outofrange"))
    return "bad-txns-accumulated-fee-outofrange";
  if (s.includes("bad-blk-sigops") || s.includes("sigops"))
    return "bad-blk-sigops";
  if (s.includes("merkle"))
    return "bad-txnmrklroot";
  if (s.includes("witness commitment"))
    return "bad-witness-merkle-match";
  if (s.includes("coinbase scriptsig") || s.includes("bad-cb-length"))
    return "bad-cb-length";
  if (s.includes("bip34") || s.includes("bad-cb-height"))
    return "bad-cb-height";
  if (s.includes("high-hash") || s.includes("proof of work"))
    return "high-hash";
  if (s.includes("script") || s.includes("checksig") || s.includes("tapscript") || s.includes("witness program") || s.includes("script verify") || s.includes("block-script-verify")) {
    return "block-script-verify-flag-failed";
  }
  return "rejected";
}
