    if (peerInfo) {
      peerInfo.count = Math.max(0, peerInfo.count - 1);
      peerInfo.lastResponse = Date.now();
      peerInfo.blocksDelivered++;
      peerInfo.stallTimeout = Math.max(BASE_STALL_TIMEOUT, Math.floor(peerInfo.stallTimeout * 0.9));
    }
    this.state.downloadedBlocks.set(hashHex, block);
    this.downloadedBlockPeers.set(hashHex, peerKey);
