// src/logger/logger.ts
import * as fs from "fs";
var DEBUG_CATEGORIES = [
  "net",
  "p2p",
  "mempool",
  "rpc",
  "validation",
  "bench",
  "blockstore",
  "leveldb",
  "txreconciliation",
  "rand",
  "tor",
  "addrman",
  "selectcoins",
  "reindex",
  "cmpctblock",
  "http",
  "libevent",
  "zmq",
  "estimatefee",
  "i2p",
  "scan",
  "ipc",
  "qt",
  "walletdb",
  "wallet",
  "coindb",
  "lock",
  "util",
  "blockchain",
  "sync",
  "headers",
  "blocks"
];
var KNOWN_CATEGORIES = new Set(DEBUG_CATEGORIES);
var ALL_TOKENS = new Set(["1", "all", ""]);
var NONE_TOKENS = new Set(["0", "none"]);
var LEVEL_ORDER = { debug: 10, info: 20, warn: 30, error: 40 };

class Logger {
  level;
  enabledCategories;
  allEnabled;
  logFilePath;
  printToConsole;
  fileStream = null;
  constructor(opts = {}) {
    this.level = opts.level ?? "info";
    this.enabledCategories = new Set;
    this.allEnabled = false;
    this.logFilePath = opts.logFilePath ?? null;
    this.printToConsole = opts.printToConsole ?? this.logFilePath === null;
    for (const c of opts.debugCategories ?? []) {
      this.enableCategory(c);
    }
    if (this.logFilePath) {
      this.openFileStream();
    }
  }
  enableCategory(raw) {
    if (raw.trim() === "") {
      this.allEnabled = true;
      for (const c of DEBUG_CATEGORIES)
        this.enabledCategories.add(c);
      return;
    }
    const tokens = raw.split(",").map((t) => t.trim().toLowerCase()).filter((t) => t.length > 0);
    for (const token of tokens) {
      if (ALL_TOKENS.has(token)) {
        this.allEnabled = true;
        for (const c of DEBUG_CATEGORIES)
          this.enabledCategories.add(c);
        continue;
      }
      if (NONE_TOKENS.has(token)) {
        this.allEnabled = false;
        this.enabledCategories.clear();
        continue;
      }
      this.enabledCategories.add(token);
    }
  }
  disableCategory(raw) {
    if (raw.trim() === "") {
      this.allEnabled = false;
      this.enabledCategories.clear();
      return;
    }
    const tokens = raw.split(",").map((t) => t.trim().toLowerCase()).filter((t) => t.length > 0);
    for (const token of tokens) {
      if (ALL_TOKENS.has(token) || NONE_TOKENS.has(token)) {
        this.allEnabled = false;
        this.enabledCategories.clear();
        continue;
      }
      if (this.allEnabled) {
        this.allEnabled = false;
        for (const c of DEBUG_CATEGORIES)
          this.enabledCategories.add(c);
      }
      this.enabledCategories.delete(token);
    }
  }
  isCategoryEnabled(category) {
    return this.allEnabled || this.enabledCategories.has(category.toLowerCase());
  }
  getCategoryStatusMap() {
    const out = {};
    for (const cat of [...DEBUG_CATEGORIES].sort()) {
      out[cat] = this.isCategoryEnabled(cat);
    }
    return out;
  }
  isKnownCategory(name2) {
    return KNOWN_CATEGORIES.has(name2.toLowerCase());
  }
  setLevel(level) {
    this.level = level;
  }
  reopenLog() {
    if (!this.logFilePath)
      return;
    try {
      this.fileStream?.end();
    } catch {}
    this.fileStream = null;
    this.openFileStream();
  }
  openFileStream() {
    if (!this.logFilePath)
      return;
    this.fileStream = fs.createWriteStream(this.logFilePath, {
      flags: "a"
    });
  }
  format(prefix, args) {
    const ts = new Date().toISOString();
    const parts = args.map((a) => typeof a === "string" ? a : safeStringify(a));
    return `${ts} ${prefix} ${parts.join(" ")}`;
  }
  write(line, isError) {
    if (this.printToConsole) {
      if (isError) {
        process.stderr.write(line + `
`);
      } else {
        process.stdout.write(line + `
`);
      }
    }
    if (this.fileStream) {
      this.fileStream.write(line + `
`);
    }
  }
  debug(category, ...args) {
    if (!this.isCategoryEnabled(category))
      return;
    this.write(this.format(`[${category}]`, args), false);
  }
  info(...args) {
    if (LEVEL_ORDER[this.level] > LEVEL_ORDER.info)
      return;
    this.write(this.format("[info]", args), false);
  }
  warn(...args) {
    if (LEVEL_ORDER[this.level] > LEVEL_ORDER.warn)
      return;
    this.write(this.format("[warn]", args), true);
  }
  error(...args) {
    if (LEVEL_ORDER[this.level] > LEVEL_ORDER.error)
      return;
    this.write(this.format("[error]", args), true);
  }
}
function safeStringify(value) {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}
var globalLogger = new Logger;
function setLogger(logger) {
  globalLogger = logger;
}
function getLogger() {
  return globalLogger;
}

