function getParams(network) {
  switch (network) {
    case "testnet":
      return TESTNET;
    case "testnet4":
      return TESTNET4;
    case "regtest":
      return REGTEST;
    default:
      return MAINNET;
  }
}
var runningNode = null;
function xorDeobfuscate(data, fileOffset, key) {
  if (key.every((b) => b === 0))
    return;
  for (let i = 0;i < data.length; i++) {
    data[i] ^= key[(fileOffset + i) % 8];
  }
}
async function detectXorKey(blocksDir, expectedMagic) {
  const filePath = path3.join(blocksDir, "blk00000.dat");
  const file = Bun.file(filePath);
  if (!await file.exists())
    return Buffer.alloc(8);
  const headerData = Buffer.from(await file.slice(0, 16).arrayBuffer());
  if (headerData.length < 16)
    return Buffer.alloc(8);
  if (headerData.subarray(0, 4).equals(expectedMagic))
    return Buffer.alloc(8);
  const key = Buffer.alloc(8);
  for (let i = 0;i < 4; i++) {
    key[i] = headerData[i] ^ expectedMagic[i];
  }
  for (let i = 0;i < 4; i++) {
    key[4 + i] = headerData[12 + i];
  }
  console.log(`Detected XOR obfuscation key: ${key.toString("hex")}`);
  return key;
}
async function runBlockImport(importPath, db, chainState, params) {
  const { deserializeBlock: deserializeBlock3, deserializeBlockHeader: deserializeBlockHeader2, getBlockHash: getBlockHash2 } = await Promise.resolve().then(() => (init_block(), exports_block));
  const { BufferReader: BufferReader4 } = await Promise.resolve().then(() => (init_serialization(), exports_serialization));
  const bestBlock = chainState.getBestBlock();
  const startHeight = bestBlock.height;
  console.log(`Block import mode: starting from height ${startHeight}`);
  if (importPath === "-") {
    await importFromStdin(startHeight, db, chainState, deserializeBlock3, BufferReader4);
  } else {
    await importFromBlkFiles(importPath, startHeight, db, chainState, params, deserializeBlock3, deserializeBlockHeader2, getBlockHash2, BufferReader4);
  }
}
async function importFromStdin(startHeight, db, chainState, deserializeBlock3, BufferReader4) {
  let imported = 0;
  const importStart = Date.now();
  let batchStart = Date.now();
  console.log("Reading blocks from stdin (framed format)...");
  const stdin = Bun.stdin.stream();
  const reader = stdin.getReader();
  let buffer = Buffer.alloc(0);
  const readExact = async (n) => {
    while (buffer.length < n) {
      const { done, value } = await reader.read();
      if (done)
        return null;
      buffer = Buffer.concat([buffer, Buffer.from(value)]);
    }
    const result = buffer.subarray(0, n);
    buffer = buffer.subarray(n);
    return Buffer.from(result);
  };
  while (true) {
    const frameHeader = await readExact(8);
    if (!frameHeader)
      break;
    const frameHeight = frameHeader.readUInt32LE(0);
    const frameSize = frameHeader.readUInt32LE(4);
    if (frameSize === 0 || frameSize > 4000000) {
      console.error(`Invalid frame size ${frameSize} at height ${frameHeight}`);
      break;
    }
    if (frameHeight <= startHeight) {
      const skipData = await readExact(frameSize);
      if (!skipData)
        break;
      continue;
    }
    const blockData = await readExact(frameSize);
    if (!blockData)
      break;
    const block = deserializeBlock3(new BufferReader4(blockData));
    try {
      await chainState.connectBlock(block, frameHeight);
    } catch (e) {
      console.error(`Block validation failed at height ${frameHeight}: ${e.message}`);
      break;
    }
    imported++;
    if (imported % 1000 === 0) {
      const elapsed = (Date.now() - batchStart) / 1000;
      const bps = 1000 / elapsed;
      const totalElapsed2 = (Date.now() - importStart) / 1000;
      console.log(`Import progress: height ${frameHeight} (${imported} blocks, ${bps.toFixed(0)} blocks/sec, ${(bps * 60).toFixed(0)} blocks/min, elapsed ${totalElapsed2.toFixed(1)}s)`);
      batchStart = Date.now();
    }
  }
  const totalElapsed = (Date.now() - importStart) / 1000;
  if (imported > 0) {
    const bps = imported / totalElapsed;
    console.log(`Import complete: ${imported} blocks in ${totalElapsed.toFixed(1)}s (${bps.toFixed(0)} blocks/sec, ${(bps * 60).toFixed(0)} blocks/min)`);
  }
}
async function importFromBlkFiles(blocksDir, startHeight, db, chainState, params, deserializeBlock3, deserializeBlockHeader2, getBlockHash2, BufferReader4) {
  const magic = Buffer.alloc(4);
  magic.writeUInt32LE(params.networkMagic, 0);
  console.log(`Scanning blk*.dat files in ${blocksDir} ...`);
  const xorKey = await detectXorKey(blocksDir, magic);
  const index = new Map;
  let fileNum = 0;
  while (true) {
    const filePath = path3.join(blocksDir, `blk${String(fileNum).padStart(5, "0")}.dat`);
    const file = Bun.file(filePath);
    if (!await file.exists())
      break;
    const fileData = Buffer.from(await file.arrayBuffer());
    let pos = 0;
    let blocksInFile = 0;
    while (pos + 8 <= fileData.length) {
      const hdr = Buffer.from(fileData.subarray(pos, pos + 8));
      xorDeobfuscate(hdr, pos, xorKey);
      if (hdr[0] === 0 && hdr[1] === 0 && hdr[2] === 0 && hdr[3] === 0) {
        break;
      }
      if (!hdr.subarray(0, 4).equals(magic)) {
        console.warn(`Bad magic at blk${String(fileNum).padStart(5, "0")}.dat offset ${pos}, skipping`);
        break;
      }
      const size = hdr.readUInt32LE(4);
      if (size === 0 || size > 4000000) {
        console.warn(`Invalid block size ${size} at blk${String(fileNum).padStart(5, "0")}.dat offset ${pos}`);
        break;
      }
      const blockOffset = pos + 8;
      const headerBuf = Buffer.from(fileData.subarray(blockOffset, blockOffset + 80));
      xorDeobfuscate(headerBuf, blockOffset, xorKey);
      const header = deserializeBlockHeader2(new BufferReader4(headerBuf));
      const hash = getBlockHash2(header);
      const hashHex = hash.toString("hex");
      index.set(hashHex, { fileNum, offset: blockOffset, size });
      blocksInFile++;
      pos = blockOffset + size;
    }
    console.log(`Scanned blk${String(fileNum).padStart(5, "0")}.dat: ${blocksInFile} blocks (total: ${index.size})`);
    fileNum++;
  }
  if (fileNum === 0) {
    console.error(`No blk*.dat files found in ${blocksDir}`);
    return;
  }
  console.log(`Block index built: ${index.size} blocks from ${fileNum} files`);
  const fileCache = new Map;
  const readBlock = async (loc) => {
    let data = fileCache.get(loc.fileNum);
    if (!data) {
      const filePath = path3.join(blocksDir, `blk${String(loc.fileNum).padStart(5, "0")}.dat`);
      data = Buffer.from(await Bun.file(filePath).arrayBuffer());
      if (fileCache.size >= 2) {
        const firstKey = fileCache.keys().next().value;
        if (firstKey !== undefined)
          fileCache.delete(firstKey);
      }
      fileCache.set(loc.fileNum, data);
    }
    return data.subarray(loc.offset, loc.offset + loc.size);
  };
  let height = startHeight + 1;
  let imported = 0;
  const importStart = Date.now();
  let batchStart = Date.now();
  while (true) {
    const hashBuf = await db.getBlockHashByHeight(height);
    if (!hashBuf) {
      console.log(`No header at height ${height} — end of header chain. Imported ${imported} blocks.`);
      break;
    }
    const hashHex = hashBuf.toString("hex");
    const loc = index.get(hashHex);
    if (!loc) {
      console.warn(`Block ${hashHex} at height ${height} not found in blk files. Stopping.`);
      break;
    }
    const blockData = Buffer.from(await readBlock(loc));
    xorDeobfuscate(blockData, loc.offset, xorKey);
    const block = deserializeBlock3(new BufferReader4(blockData));
    try {
      await chainState.connectBlock(block, height);
    } catch (e) {
      console.error(`Block validation failed at height ${height}: ${e.message}`);
      break;
    }
    imported++;
    height++;
    if (imported % 1000 === 0) {
      const elapsed = (Date.now() - batchStart) / 1000;
      const bps = 1000 / elapsed;
      const totalElapsed2 = (Date.now() - importStart) / 1000;
      console.log(`Import progress: height ${height - 1} (${imported} blocks, ${bps.toFixed(0)} blocks/sec, ${(bps * 60).toFixed(0)} blocks/min, elapsed ${totalElapsed2.toFixed(1)}s)`);
      batchStart = Date.now();
    }
  }
  const totalElapsed = (Date.now() - importStart) / 1000;
  if (imported > 0) {
    const bps = imported / totalElapsed;
    console.log(`Import complete: ${imported} blocks in ${totalElapsed.toFixed(1)}s (${bps.toFixed(0)} blocks/sec, ${(bps * 60).toFixed(0)} blocks/min)`);
  }
}
async function runSnapshotLoad(snapshotPath, db, chainState, params) {
  console.log(`Loading Core-format UTXO snapshot: ${snapshotPath}`);
  const manager = new ChainstateManager(db, params);
  const result = await manager.loadSnapshot(snapshotPath);
  console.log(`Loaded ${result.coinsLoaded} coins`);
  console.log(`  Base height: ${result.baseHeight}`);
  console.log(`  Base block:  ${Buffer.from(result.baseBlockHash).reverse().toString("hex")}`);
  await db.putChainState({
    bestBlockHash: result.baseBlockHash,
    bestHeight: result.baseHeight,
    totalWork: params.nMinimumChainWork
  });
  const dummyHeader = Buffer.alloc(80);
  await db.putBlockIndex(result.baseBlockHash, {
    height: result.baseHeight,
    header: dummyHeader,
    nTx: 0,
    status: 1 /* HEADER_VALID */ | 4 /* TXS_VALID */ | 8 /* HAVE_DATA */,
    dataPos: 0
  });
  console.log(`Snapshot load complete. Chain tip: height ${result.baseHeight}, hash ` + Buffer.from(result.baseBlockHash).reverse().toString("hex"));
}
function daemonizeAndExit(originalArgv) {
  const childArgs = originalArgv.slice(2).filter((arg) => {
    if (arg === "--daemon")
      return false;
    if (arg.startsWith("--daemon="))
      return false;
    return true;
  });
  childArgs.push("--internal-daemon-child");
  const bunExe = process.execPath;
  const scriptPath = originalArgv[1];
  const child = Bun.spawn([bunExe, "run", scriptPath, ...childArgs], {
    stdio: ["ignore", "ignore", "ignore"],
    cwd: process.cwd(),
    env: process.env
  });
  child.unref?.();
  console.log(`hotbuns daemonized as pid ${child.pid}`);
  process.exit(0);
}
async function writePidFile(pidPath) {
  try {
    await fs2.promises.writeFile(pidPath, `${process.pid}
`, { flag: "w" });
  } catch (e) {
    console.error(`Failed to write PID file ${pidPath}:`, e.message);
  }
}
function removePidFileSync(pidPath) {
  if (!pidPath)
    return;
  try {
    fs2.unlinkSync(pidPath);
  } catch {}
}
var activePidPath = null;
async function migrateNTxBackfill(db, network, datadir) {
  const missing = [];
  for await (const [hash, record] of db.iterateBlockIndexEntries()) {
    if (record.nTx === 0 && record.height > 0) {
      missing.push({ hash, height: record.height });
    }
  }
  if (missing.length === 0) {
    return;
  }
  console.log(`[nTx-migrate] ${missing.length} block index entries with nTx=0 — backfilling...`);
  let fixedFromBlock = 0;
  let fixedFromCore = 0;
  let failed = 0;
  const stillMissing = [];
  for (const { hash, height } of missing) {
    const rawBlock = await db.getBlock(hash);
    if (rawBlock !== null) {
      try {
        const blk = deserializeBlock(new BufferReader(rawBlock));
        await db.updateBlockIndexNTx(hash, blk.transactions.length);
        fixedFromBlock++;
      } catch {
        failed++;
      }
    } else {
      stillMissing.push({ hash, height });
    }
  }
  if (stillMissing.length > 0 && network === "mainnet") {
    const coreDatadir = path3.join(path3.dirname(datadir), "bitcoin-core");
    const cookiePath = path3.join(coreDatadir, ".cookie");
    let cookie = null;
    try {
      cookie = (await Bun.file(cookiePath).text()).trim();
    } catch {}
    if (cookie) {
      for (const { hash, height } of stillMissing) {
        const hashHex = Buffer.from(hash).reverse().toString("hex");
        try {
          const resp = await fetch("http://127.0.0.1:8332/", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Basic " + Buffer.from(cookie).toString("base64")
            },
            body: JSON.stringify({
              jsonrpc: "1.0",
              id: "ntx-migrate",
              method: "getblockheader",
              params: [hashHex, true]
            })
          });
          if (resp.ok) {
            const data = await resp.json();
            const nTx = data?.result?.nTx;
            if (typeof nTx === "number" && nTx > 0) {
              await db.updateBlockIndexNTx(hash, nTx);
              fixedFromCore++;
            } else {
              failed++;
            }
          } else {
            failed++;
          }
        } catch {
          failed++;
        }
      }
    } else {
      failed += stillMissing.length;
    }
  } else if (stillMissing.length > 0) {
    failed += stillMissing.length;
  }
  console.log(`[nTx-migrate] done: ${fixedFromBlock} from block data, ${fixedFromCore} from Core RPC, ${failed} unreachable`);
}
